using CTXD.Server.Data;
using Npgsql;
namespace CTXD.Server.Services;
public sealed class NationTaskScheduler(GameDb db,CanonicalContent content,GamePushHub push,ILogger<NationTaskScheduler> log):BackgroundService
{
 static readonly (TimeSpan start,TimeSpan end,int division,int ordinal)[] Slots=[(new(10,0,0),new(11,30,0),1,1),(new(15,0,0),new(16,30,0),3,2),(new(20,0,0),new(21,30,0),5,3)];static readonly int[] Capitals=[123,19,207];
 protected override async Task ExecuteAsync(CancellationToken ct){using var timer=new PeriodicTimer(TimeSpan.FromSeconds(30));do{try{await TickAsync(ct);}catch(OperationCanceledException)when(ct.IsCancellationRequested){return;}catch(Exception ex){log.LogError(ex,"Nation task scheduler tick failed");}}while(await timer.WaitForNextTickAsync(ct));}
 async Task TickAsync(CancellationToken ct){var local=DateTimeOffset.Now;var slot=Slots.FirstOrDefault(x=>local.TimeOfDay>=x.start&&local.TimeOfDay<x.end);await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);await using(var old=new NpgsqlCommand("UPDATE nation_scheduled_tasks SET status=CASE WHEN dependency_code='' THEN 1 ELSE 2 END WHERE status=0 AND ends_at<=now();UPDATE nation_forces SET task_won=(task_progress>=task_target),updated_at=now() WHERE task_type=4 AND task_ends_at<=now()",c,t))await old.ExecuteNonQueryAsync(ct);if(slot.division==0){await t.CommitAsync(ct);return;}DateOnly epoch;await using(var state=new NpgsqlCommand("SELECT epoch_date FROM nation_scheduler_state WHERE singleton=1 FOR UPDATE",c,t))epoch=(DateOnly)(await state.ExecuteScalarAsync(ct))!;var day=Math.Max(1,DateOnly.FromDateTime(local.DateTime).DayNumber-epoch.DayNumber+1);var key=$"{local:yyyyMMdd}-{slot.division}";await using(var exists=new NpgsqlCommand("SELECT 1 FROM nation_scheduled_tasks WHERE slot_key=$1",c,t)){exists.Parameters.AddWithValue(key);if(await exists.ExecuteScalarAsync(ct)is not null){await t.CommitAsync(ct);return;}}var compose=day*100+slot.ordinal;var type=content.NationTaskInitial.TryGetValue(compose,out var init)?init.TaskType:Fallback();var start=new DateTimeOffset(local.Year,local.Month,local.Day,slot.start.Hours,slot.start.Minutes,0,local.Offset);var end=new DateTimeOffset(local.Year,local.Month,local.Day,slot.end.Hours,slot.end.Minutes,0,local.Offset);if(type==1&&!await CompetitionAsync(c,t,key,slot.division,start,end,ct))type=4;if(type!=1)await StandardAsync(c,t,key,type,start,end,ct);await using(var save=new NpgsqlCommand("UPDATE nation_scheduler_state SET last_slot_key=$1,updated_at=now() WHERE singleton=1",c,t)){save.Parameters.AddWithValue(key);await save.ExecuteNonQueryAsync(ct);}await t.CommitAsync(ct);await push.BroadcastAsync("nation.updated",new{reason="nation.task.start",taskType=type,slot=key},ct);}
 async Task StandardAsync(NpgsqlConnection c,NpgsqlTransaction t,string key,int type,DateTimeOffset start,DateTimeOffset end,CancellationToken ct){var serial=type is 6 or 7 or 8 or 9?1:0;long target=0;if(type is 6 or 8)end=start.AddMinutes(30);if(type==4){var choices=content.InvestmentEvents.Where(x=>x.T==0).GroupBy(x=>x.S).Select(x=>x.First()).ToArray();var ev=choices[Random.Shared.Next(choices.Length)];serial=ev.S;target=ev.Cm;}for(var force=1;force<=3;force++){var ft=target;if(type==6){long owned;await using(var q=new NpgsqlCommand("SELECT count(*) FROM world_cities WHERE owner_force_id=$1",c,t)){q.Parameters.AddWithValue(force);owned=Convert.ToInt64(await q.ExecuteScalarAsync(ct));}var wins=0;var x=content.NationExpansionTargets.FirstOrDefault(x=>x.Win==wins)??content.NationExpansionTargets.OrderBy(x=>Math.Abs(x.Win-wins)).First();ft=owned+x.Tc;}var id=force*100+type+(type is 4 or 6 or 7 or 8 or 9?serial*10:0);await InsertAsync(c,t,key,force,type,id,ft,start,end,Dependency(type),serial,null,ct);if(type==4){await using var q=new NpgsqlCommand("UPDATE nation_forces SET task_type=4,task_event_serial=$4,task_target=$2,task_progress=0,task_ends_at=$3,task_won=false,updated_at=now() WHERE force_id=$1 AND (task_ends_at IS NULL OR task_ends_at<=now())",c,t);q.Parameters.AddWithValue(force);q.Parameters.AddWithValue(ft);q.Parameters.AddWithValue(end);q.Parameters.AddWithValue(serial);await q.ExecuteNonQueryAsync(ct);}}}
 async Task<bool> CompetitionAsync(NpgsqlConnection c,NpgsqlTransaction t,string key,int division,DateTimeOffset start,DateTimeOffset end,CancellationToken ct){var owners=new Dictionary<int,int>();await using(var q=new NpgsqlCommand("SELECT city_id,owner_force_id FROM world_cities",c,t))await using(var r=await q.ExecuteReaderAsync(ct))while(await r.ReadAsync(ct))owners[r.GetInt32(0)]=r.GetInt16(1);if(owners.Count==0)return false;var levels=new Dictionary<int,int>();await using(var q=new NpgsqlCommand("SELECT force_id,level FROM nation_forces",c,t))await using(var r=await q.ExecuteReaderAsync(ct))while(await r.ReadAsync(ct))levels[r.GetInt16(0)]=r.GetInt32(1);var counts=Enumerable.Range(1,3).ToDictionary(x=>x,x=>owners.Values.Count(v=>v==x));var max=counts.Values.Max();var ds=counts.Where(x=>x.Value==max).Select(x=>x.Key).ToArray();var defender=ds[Random.Shared.Next(ds.Length)];var chosen=new List<int>();var reverse=Random.Shared.Next(2)==1;foreach(var attacker in Enumerable.Range(1,3).Where(x=>x!=defender)){var target=await BoundaryAsync(c,t,owners,levels,defender,attacker,reverse?[2,1]:[1,2],chosen,ct);reverse=!reverse;if(target==0)return false;chosen.Add(target);}for(var force=1;force<=3;force++)for(var j=0;j<2;j++)await InsertAsync(c,t,key,force,1,force*10+division+j,chosen[j],start,end,"",0,owners[chosen[j]],ct);return true;}
 async Task<int> BoundaryAsync(NpgsqlConnection c,NpgsqlTransaction t,Dictionary<int,int> owners,Dictionary<int,int> levels,int defender,int attacker,int[] types,List<int> selected,CancellationToken ct){foreach(var type in types)foreach(var road in content.NationCompetitionRoads.Where(x=>x.Type==type&&Concerned(x.Id,defender,attacker)).OrderBy(_=>Random.Shared.Next())){var ids=Parse(road.Cities);for(var i=0;i<ids.Length-1;i++){var a=ids[i];var b=ids[i+1];if(!((owners.GetValueOrDefault(a)==defender)^(owners.GetValueOrDefault(b)==defender)))continue;var dc=owners.GetValueOrDefault(a)==defender?a:b;var other=dc==a?b:a;var pick=Random.Shared.Next(2)==0?dc:other;if(owners.GetValueOrDefault(pick)!=attacker||Capitals.Contains(pick))pick=dc;if(levels.GetValueOrDefault(defender)!=levels.GetValueOrDefault(attacker)&&Random.Shared.NextDouble()<=.3){var back=levels.GetValueOrDefault(defender)>levels.GetValueOrDefault(attacker)?attacker:defender;var at=Array.IndexOf(ids,pick);foreach(var n in new[]{at-1,at+1})if(n>=0&&n<ids.Length&&owners.GetValueOrDefault(ids[n])==back&&!Capitals.Contains(ids[n])&&await FreeAsync(c,t,ids[n],ct)){pick=ids[n];break;}}if(!selected.Contains(pick)&&!Capitals.Contains(pick)&&await FreeAsync(c,t,pick,ct))return pick;}}return 0;}
 static async Task InsertAsync(NpgsqlConnection c,NpgsqlTransaction t,string key,int force,int type,int id,long target,DateTimeOffset start,DateTimeOffset end,string dep,int serial,int? owner,CancellationToken ct){await using var q=new NpgsqlCommand("INSERT INTO nation_scheduled_tasks(slot_key,force_id,task_type,task_id,target,starts_at,ends_at,status,dependency_code,event_serial,initial_owner_force_id) VALUES($1,$2,$3,$4,$5,$6,$7,0,$8,$9,$10)",c,t);q.Parameters.AddWithValue(key);q.Parameters.AddWithValue(force);q.Parameters.AddWithValue(type);q.Parameters.AddWithValue(id);q.Parameters.AddWithValue(target);q.Parameters.AddWithValue(start);q.Parameters.AddWithValue(end);q.Parameters.AddWithValue(dep);q.Parameters.AddWithValue(serial);q.Parameters.AddWithValue((object?)owner??DBNull.Value);await q.ExecuteNonQueryAsync(ct);}
 static async Task<bool> FreeAsync(NpgsqlConnection c,NpgsqlTransaction t,int city,CancellationToken ct){await using var q=new NpgsqlCommand("SELECT NOT EXISTS(SELECT 1 FROM world_battle_handoffs WHERE city_id=$1 AND status=0)",c,t);q.Parameters.AddWithValue(city);return Convert.ToBoolean(await q.ExecuteScalarAsync(ct));}static bool Concerned(int road,int a,int b){var p=(road%100).ToString();return p.Contains(a.ToString())&&p.Contains(b.ToString());}static int[] Parse(string s)=>s.Split(';',StringSplitOptions.RemoveEmptyEntries).Select(int.Parse).ToArray();int Fallback(){var vs=content.NationTaskTypes.Values.OrderBy(x=>x.Id);var roll=Random.Shared.NextDouble();double sum=0;foreach(var v in vs){sum+=v.Prob;if(roll<=sum)return v.Id;}return 1;}static string Dependency(int type)=>type==8?"battle.queued-duel":"";
}

